class Solution {
public:
    int canCompleteCircuit(vector<int>& gas, vector<int>& cost) {
        int start=0;
        int totalsurplus=0,surplus=0;
        int n=gas.size();
        for(int i=0;i<n;i++)
        {
            totalsurplus+=gas[i]-cost[i];
            surplus+=gas[i]-cost[i];
            if(surplus<0)
            {
                surplus=0;
                start=i+1;
            }
        }
        if(totalsurplus<0)
            return -1;
        return start;
    }
};

class Solution(object):
    def canCompleteCircuit(self, gas, cost):
        """
        :type gas: List[int]
        :type cost: List[int]
        :rtype: int
        """
        n = len(gas)
        i = 0
        while i < n:
            gas_sum, cost_sum, cnt = 0, 0, 0
            while cnt < n:
                j = (i + cnt) % n
                gas_sum += gas[j]
                cost_sum += cost[j]
                if gas_sum < cost_sum:
                    break
                cnt += 1
            if cnt == n:
                return i
            else:
                i = i + cnt + 1
        return -1
